"""
Provide common methods for creation of collector configuration for gNodeB.
"""


class GnbProtocolsCollectorConfigurator:
    """
    Common methods for creation of configuration for protocols logs collection

    Attributes:
        supported_interfaces: all supported interfaces
    """
    supported_interfaces: tuple = ("f1c", "e1c", "ngc", "xnc", "x2c")

    @staticmethod
    def _get_interfaces_from_configuration(configuration: dict) -> list:
        return configuration['interfaces'].lower().replace(" ", "").split(',')

    def _verify_configuration(self, configuration: dict) -> None:
        if "interfaces" not in configuration:
            raise ValueError("There is no information about interfaces. Please provide this information in configuration. "
                             "e.g: {'type': 'protocols', 'interfaces': 'e1c, f1c'}. "
                             f"Available interfaces: {self.supported_interfaces}")
        interfaces = self._get_interfaces_from_configuration(configuration)
        invalid_interfaces = [i for i in interfaces if i not in self.supported_interfaces]
        if invalid_interfaces:
            raise ValueError(f"Library does not support interfaces: {', '.join(invalid_interfaces)}. "
                             f"Supported interfaces are: {', '.join(self.supported_interfaces)}")
